local M=require('retgtk.core');return function(p) local w=M.widget('entry',p);function w:paint(r,c) local clicked,focused=M.control(self,r,c);if focused then local text=self.text;if c.input.backspace then local i=#text;while i>1 and string.byte(text,i)>=128 and string.byte(text,i)<192 do i=i-1 end;text=string.sub(text,1,i-1) end;if c.input.text then text=text..c.input.text end;self:set('text',text) end end;return w end
